std::string get_url_to_visit(const std::string& domain, const std::string& subdomain_prefix) {
    if (subdomain_prefix.empty()) {
        return "https://" + domain;
    }

    // Split the subdomain prefix into parts if it contains dots
    std::istringstream iss(subdomain_prefix);
    std::vector<std::string> subdomain_parts;
    std::string part;
    while (std::getline(iss, part, '.')) {
        if (part.empty()) {
            throw std::invalid_argument("Subdomain prefix contains invalid segments.");
        }
        subdomain_parts.push_back(part);
    }

    // Check if the domain has a valid format (e.g., contains a dot)
    if (domain.find('.') == std::string::npos) {
        throw std::invalid_argument("Domain must contain a dot.");
    }

    // Construct the full subdomain by joining the parts with dots
    std::ostringstream oss;
    for (size_t i = 0; i < subdomain_parts.size(); ++i) {
        oss << subdomain_parts[i];
        if (i != subdomain_parts.size() - 1) {
            oss << ".";
        }
    }

    // Combine with the domain
    return "https://" + oss.str() + "." + domain;
}
